  }
}

/** Position dans le plan de l'orbite pour une anomalie excentrique E. */
function positionInOrbitalPlane(a, e, E) {
  return {
    xp: a * (Math.cos(E) - e),
    yp: a * Math.sqrt(1 - e * e) * Math.sin(E),
