const exp = window.experience;
exp.clock.paused = true;
await new Promise(r => setTimeout(r, 300));
const jupiter = exp.world.planets.find(p => p.key === 'jupiter');
const v = jupiter.mesh.position.clone().project(exp.camera.instance);
const x = (v.x + 1) / 2 * exp.sizes.width, y = (1 - v.y) / 2 * exp.sizes.height;
const canvas = exp.canvas;
const opts = { clientX: x, clientY: y, bubbles: true, pointerId: 1 };
canvas.dispatchEvent(new PointerEvent('pointerdown', opts));
canvas.dispatchEvent(new PointerEvent('pointerup', opts));
const afterSelect = { selected: exp.selection.selected?.label, info: document.querySelector('.info').innerText, camDist: exp.camera.instance.position.distanceTo(jupiter.mesh.position).toFixed(2) };
exp.clock.paused = false; exp.clock.daysPerSecond = 365.25;
await new Promise(r => setTimeout(r, 1500));
const afterMove = { camDist: exp.camera.instance.position.distanceTo(jupiter.mesh.position).toFixed(2), targetGap: exp.camera.controls.target.distanceTo(jupiter.mesh.position).toFixed(3) };
window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }));
({ screen: [x.toFixed(0), y.toFixed(0)], afterSelect, afterMove, afterEscape: exp.selection.selected, infoHidden: document.querySelector('.info').classList.contains('hidden') })

