await new Promise(r => setTimeout(r, 1500));
const exp = window.experience;
exp.clock.paused = true;
const ctrls = exp.controls.gui.controllersRecursive();
const mode = ctrls.find(c => c.property === 'mode');
const expo = ctrls.find(c => c.property === 'exponent');
const snapshot = (label) => {
  const nep = exp.world.planets[7], mer = exp.world.planets[0];
  const orbitPts = nep.orbit.geometry.attributes.position;
  return { label, neptune: nep.mesh.position.length().toFixed(1), mercure: mer.mesh.position.length().toFixed(2), sun: exp.world.sun.radius.toFixed(2), camDist: exp.camera.instance.position.length().toFixed(0), expoVisible: !expo._hidden, nepOrbitFirstPt: Math.hypot(orbitPts.getX(0), orbitPts.getY(0), orbitPts.getZ(0)).toFixed(1) };
};
const out = [snapshot('sqrt')];
for (const m of ['real', 'log', 'rails', 'power']) { mode.setValue(m); out.push(snapshot(m)); }
expo.setValue(1); out.push(snapshot('power p=1'));
mode.setValue('sqrt');
({ out, options: [...mode.$select.options].map(o => o.textContent), folders: exp.controls.gui.folders.map(f => f._title) })

